export class ChatSalaComponent implements OnInit {
  private destroyRef = inject(DestroyRef);
  mensagens: Mensagem[] = [];
  digitando = false;

  ngOnInit(): void {
    // A
    this.chatHub.novaMensagem$
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(m => this.mensagens.push(m));

    // B
    this.chatHub.alguemDigitando$
      .subscribe(valor => this.digitando = valor);
  }
}

export class DocumentosComponent implements OnInit {
  // linha 1: ______________________

  ngOnInit(): void {
    this.documentoService.documentoSelecionado$
      // linha 2: ______________________
      .subscribe(doc => this.selecionado = doc);
  }
}
